-- DROP PROCEDURE "HadoopMigration".updatecontroltable();

CREATE OR REPLACE PROCEDURE "HadoopMigration".updatecontroltable()
 LANGUAGE plpgsql
AS $procedure$																									
DECLARE																									
																									
totalcount  INTEGER := 0;																									
mincounter INTEGER := 0;																									
maxcounter INTEGER := 0;																									
BEGIN																									
																									
select count(*) INTO totalcount from "HadoopMigration".coa_hadoop  WHERE (coa_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND coa_hadoop.createdon < CURRENT_DATE) OR (coa_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND coa_hadoop.modifiedon < CURRENT_DATE);																									
select min(sequenceid) INTO mincounter from "HadoopMigration".coa_hadoop WHERE (coa_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND coa_hadoop.createdon < CURRENT_DATE) OR (coa_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND coa_hadoop.modifiedon < CURRENT_DATE);																									
select max(sequenceid) INTO maxcounter from "HadoopMigration".coa_hadoop WHERE (coa_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND coa_hadoop.createdon < CURRENT_DATE) OR (coa_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND coa_hadoop.modifiedon < CURRENT_DATE);																									
INSERT INTO "HadoopMigration".hadoop_migration_control_table VALUES ('coa',totalcount,mincounter,maxcounter,current_date, current_date - 1 );																									
																									
select count(*) INTO totalcount from "HadoopMigration".currency_hadoop  WHERE (currency_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND currency_hadoop.createdon < CURRENT_DATE) OR (currency_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND currency_hadoop.modifiedon < CURRENT_DATE);																									
select min(sequenceid) INTO mincounter from "HadoopMigration".currency_hadoop WHERE (currency_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND currency_hadoop.createdon < CURRENT_DATE) OR (currency_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND currency_hadoop.modifiedon < CURRENT_DATE);																									
select max(sequenceid) INTO maxcounter from "HadoopMigration".currency_hadoop WHERE (currency_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND currency_hadoop.createdon < CURRENT_DATE) OR (currency_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND currency_hadoop.modifiedon < CURRENT_DATE);																									
INSERT INTO "HadoopMigration".hadoop_migration_control_table VALUES ('currency',totalcount,mincounter,maxcounter,current_date, current_date - 1 );																									
																									
