-- dashboard.account_balance source

CREATE OR REPLACE VIEW dashboard.account_balance
AS SELECT coa_agg.parent AS "GL Head",
    coa_agg.name AS "GL Name",
    balance.account_name AS "Account Name",
        CASE
            WHEN coa_agg.parent::text ~~ '%ASSET%'::text OR coa_agg.parent::text ~~ '%EXP%'::text THEN
            CASE
                WHEN balance.bal < 0::numeric THEN ('('::text || replace(round(balance.bal, 2)::text, '-'::text, ''::text)) || ')'::text
                ELSE round(balance.bal, 2)::text
            END
            ELSE ''::text
        END AS "Debit",
        CASE
            WHEN coa_agg.parent::text ~~ '%LIAB%'::text OR coa_agg.parent::text ~~ '%INCOME%'::text THEN
            CASE
                WHEN balance.bal < 0::numeric THEN ('('::text || replace(round(balance.bal, 2)::text, '-'::text, ''::text)) || ')'::text
                ELSE round(balance.bal, 2)::text
            END
            ELSE ''::text
        END AS "Credit",
    balance.bal * '-1'::integer::numeric AS "Balance",
    cur.name AS "Currency"
   FROM ( SELECT wtype.id,
            wtype.parentglid,
            wtype.name AS account_name,
            wbalance.instancetype,
            wbalance.currencyid,
            sum(wbalance.totalbalance) * '-1'::integer::numeric AS bal
           FROM walletbalance wbalance
             JOIN wallettype wtype ON wtype.id::text = wbalance.wallettypeid::text
          GROUP BY wtype.id, wtype.parentglid, wtype.name, wbalance.instancetype, wbalance.currencyid) balance
     LEFT JOIN ( SELECT t1.id,
            t1.name,
            t1.description,
            'ASSET'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'ASSET'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'ASSET'::text), '%')
        UNION
         SELECT t1.id,
            t1.name,
            t1.description,
            'INCOME'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'INCOME'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'INCOME'::text), '%')
        UNION
         SELECT t1.id,
            t1.name,
            t1.description,
            'LIABILITY'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'LIABILITY'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'LIABILITY'::text), '%')
        UNION
         SELECT t1.id,
            t1.name,
            t1.description,
            'EXPENDITURE'::text AS category,
            ( SELECT DISTINCT coa.name
                   FROM coa
                  WHERE coa.name::text = 'EXPENDITURE'::text) AS parent,
            t1.coacode,
            t1.creditamount,
            t1.debitamount,
            ( SELECT currency.name
                   FROM currency
                  WHERE t1.currencyid::text = currency.id::text) AS currency
           FROM coa t1
          WHERE t1.coacode::text ~~ concat(( SELECT DISTINCT coa.coacode::numeric AS coacode
                   FROM coa
                  WHERE coa.name::text = 'EXPENDITURE'::text), '%')
  ORDER BY 5) coa_agg ON coa_agg.id::text = balance.parentglid::text
     LEFT JOIN currency cur ON cur.id::text = balance.currencyid::text
  ORDER BY (
        CASE
            WHEN coa_agg.parent::text = 'ASSET'::text THEN 1
            WHEN coa_agg.parent::text = 'LIABILITY'::text THEN 2
            WHEN coa_agg.parent::text = 'INCOME'::text THEN 3
            WHEN coa_agg.parent::text = 'EXPENDITURE'::text THEN 4
            ELSE NULL::integer
        END);


