-- dashboard.account_balance_historical source

CREATE OR REPLACE VIEW dashboard.account_balance_historical
AS SELECT t.createdon::date AS createdon,
    t.name AS "Name",
    t.coregltype AS "Core GL Type",
    round(t.creditamount, 2) AS "Credit Amount",
    round(t.debitamount, 2) AS "Debit Amount",
    round(t.totalbalance, 2) AS "Total Balance",
    t.glaccountnumber AS "GL Account No.",
    t.row_num AS "Row Num"
   FROM ( SELECT coaaccountbalancedata.createdon,
            coaaccountbalancedata.name,
            coaaccountbalancedata.coregltype,
            coaaccountbalancedata.creditamount,
            coaaccountbalancedata.debitamount,
            coaaccountbalancedata.totalbalance,
            coaaccountbalancedata.glaccountnumber,
            row_number() OVER (PARTITION BY coaaccountbalancedata.name ORDER BY coaaccountbalancedata.createdon DESC) AS row_num
           FROM coaaccountbalancedata) t
  WHERE t.row_num = 1
  ORDER BY (t.createdon::date) DESC;


-- dashboard.active_cust source

CREATE OR REPLACE VIEW dashboard.active_cust
AS SELECT u.id AS bankaccountid,
    u.firstname,
    u.middlename AS othername,
    u.lastname,
    u.mobilenumber,
    u.createdon AS registrationdate,
    max(wt.txtime) AS transactiondateandtime,
    count(wt.id) AS nooftransactions
   FROM users u
     LEFT JOIN wallettransactions wt ON u.id::text = wt.fromortouserid::text
  GROUP BY u.id;


-- dashboard.active_user_login_report source

CREATE OR REPLACE VIEW dashboard.active_user_login_report
AS SELECT DISTINCT users.walletfunded AS "Wallet Funded",
    users.mobilenumber AS "Mobile No.",
    users.idtype AS "ID Type",
    users.idnumber AS "ID Number",
    users.userstatus AS "User Status",
    to_char(users.lastlogin, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Last Login",
    users.transactionsource AS "Transaction Source",
    users.location AS "Location",
    users.firstname AS "First Name",
    users.middlename AS "Middle Name",
    users.lastname AS "Last Name",
    users.username AS "User Name",
    users.roletype AS "Role",
    users.channel AS "Channel",
        CASE
            WHEN users.roletype::text = 'BUSINESS_ASSOCIATE'::text THEN concat(users.firstname, ' ', users.location)
            ELSE concat(users.firstname, ' ', users.lastname)
        END AS "Name"
   FROM users
  WHERE users.userstatus::text = 'ACTIVE'::text AND users.roletype::text <> 'OPERATION'::text AND date(users.lastlogin) >= (CURRENT_DATE - '180 days'::interval)
  ORDER BY (to_char(users.lastlogin, 'yyyy-mm-dd HH24:MI:SS'::text));


-- dashboard.active_user_transaction_report source

CREATE OR REPLACE VIEW dashboard.active_user_transaction_report
AS SELECT users.mobilenumber AS "Mobile Number",
    users.idtype AS "ID Type",
    users.idnumber AS "ID Number",
    users.transactionsource AS "Transaction Source",
    to_char(users.lasttransactionon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Last Transaction On",
    to_char(wt.txtime, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Transaction Time",
        CASE
            WHEN users.roletype::text = 'BUSINESS_ASSOCIATE'::text THEN concat(users.firstname, ' ', users.location)
            ELSE concat(users.firstname, ' ', users.lastname)
        END AS "Name",
    users.firstname AS "First Name",
    users.middlename AS "Middle Name",
    users.lastname AS "Last Name",
    users.location AS "Location",
    users.username AS "UserName",
    users.roletype AS "Role",
    channel.name AS "Channel Name"
   FROM ( SELECT t.ownerid,
            t.txtime,
            t.channelid,
            t.row_num
           FROM ( SELECT wallettransactions.ownerid,
                    wallettransactions.txtime,
                    wallettransactions.channelid,
                    row_number() OVER (PARTITION BY wallettransactions.ownerid ORDER BY wallettransactions.txtime DESC) AS row_num
                   FROM wallettransactions) t
          WHERE t.row_num = 1
          ORDER BY t.txtime DESC) wt
     JOIN channel ON wt.channelid::text = channel.id::text
     JOIN users ON users.id::text = wt.ownerid::text
  WHERE users.roletype::text <> 'OPERATION'::text AND users.userstatus::text = 'ACTIVE'::text AND date(wt.txtime) >= (CURRENT_DATE - '180 days'::interval);


-- dashboard.autosweep source

CREATE OR REPLACE VIEW dashboard.autosweep
AS SELECT us.username AS "Merchant ID",
    us.firstname AS "Merchant Name",
    wtbt.payeeaccountnumber AS "Account Number",
    round(wtbt.amount::numeric, 2) AS "Amount Of Sweep",
    date(wtbt.createdon) AS "Date Of Sweep",
    'From Absa wallet to Bank Account'::text AS "Description",
    rl.roletype AS "Role Type",
    rl.name AS "Role Name"
   FROM autosweeptxdetails atd
     LEFT JOIN wallettobanktxdetails wtbt ON atd.executionid::text = wtbt.executionid::text
     LEFT JOIN users us ON wtbt.userid::text = us.id::text
     LEFT JOIN role rl ON us.roleid::text = rl.id::text
  WHERE lower(atd.transactionstatus::text) = 'processed'::text
  ORDER BY wtbt.createdon DESC;


-- dashboard.blocked_users source

CREATE OR REPLACE VIEW dashboard.blocked_users
AS SELECT usr.id AS userid,
    usr.username AS "User Name",
    usr.userstatus AS "User Status",
    audt.modifiedby AS "Blocked Modified Date",
    audt.blockedbyname AS "Blocked By",
    to_char(audt.modifiedon, 'yyyy-mm-dd HH24:MI:SS'::text) AS "Blocked Date",
    rol.name AS "Role Name",
    rol.roletype AS "Role Type",
    audt.remarks AS "Remarks"
   FROM ( SELECT users.id,
            users.username,
            users.userstatus,
            users.roleid
           FROM users
          WHERE users.userstatus::text ~~ '%BLOCK%'::text) usr
     LEFT JOIN ( SELECT ua.id,
            ua.modifiedby,
            u.username::text AS blockedbyname,
            ua.modifiedon,
            ua.remarks
           FROM usersaudit ua
             JOIN ( SELECT usersaudit.id,
                    max(usersaudit.modifiedon) AS modifiedon
                   FROM usersaudit
                  WHERE lower(usersaudit.userstatus::text) ~~ '%block%'::text
                  GROUP BY usersaudit.id) latestblock ON ua.id::text = latestblock.id::text AND ua.modifiedon = latestblock.modifiedon AND lower(ua.userstatus::text) ~~ '%block%'::text
             JOIN users u ON u.id::text = ua.modifiedby::text) audt ON audt.id::text = usr.id::text
     LEFT JOIN role rol ON rol.id::text = usr.roleid::text;


