    concat(users.firstname, ' ', users.lastname) AS "Customer Name",
    'GHS'::text AS "Currency",
    elevycancelexceptionreport.transactionamount AS "Transaction Amount",
    u1.username AS "Receiver",
    '300303'::text AS "Receiver Sort Code",
    elevycancelexceptionreport.elevyamount AS "eLevy Amount",
