   FROM elevycancelexceptionreport
     JOIN users ON users.id::text = elevycancelexceptionreport.fromuserid::text
     JOIN users u1 ON u1.id::text = elevycancelexceptionreport.touserid::text
     JOIN externalcharges ON externalcharges.clienttrxid::text = elevycancelexceptionreport.clienttrxid::text;


