                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN NULL::character varying
                    ELSE rl.name
                END AS rolename,
            trns.debitamount,
            trns.pairid,
            trns.createdon,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            trns.description,
            trns.remarks
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.businesstrxid,
                        CASE
                            WHEN wallettransactions.instancetype::text = 'CUSTOMER'::text AND (wallettransactions.fromortouserid::text = ''::text OR wallettransactions.fromortouserid IS NULL) THEN wallettransactions.ownerid
                            ELSE wallettransactions.fromortouserid
                        END AS fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.createdon,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype,
                    wallettransactions.remarks
                   FROM wallettransactions
                  WHERE wallettransactions.debitamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.fromuser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.createdon,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype,
                    pendingtransaction.remarks
                   FROM pendingtransaction) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text) dr
     JOIN ( SELECT trns.executionid,
            trns.businesstrxid,
            trns.fromortouserid,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN wtype.name
                    ELSE usr.username
                END AS username,
                CASE
                    WHEN lower(trns.instancetype::text) ~~ '%business%'::text THEN NULL::character varying
                    ELSE rl.name
                END AS rolename,
            trns.creditamount,
            trns.pairid,
            trns.createdon,
            trns.businessproductid AS trns_type_id,
                CASE
                    WHEN trns.parentid IS NULL THEN bp.name
                    ELSE c.name
                END AS transaction_type,
            trns.transactionstatus,
            trns.channelid,
            ch.name AS channel_name,
            trns.description,
            trns.remarks
           FROM ( SELECT wallettransactions.executionid,
                    wallettransactions.businesstrxid,
                        CASE
                            WHEN wallettransactions.instancetype::text = 'CUSTOMER'::text AND (wallettransactions.fromortouserid::text = ''::text OR wallettransactions.fromortouserid IS NULL) THEN wallettransactions.ownerid
                            ELSE wallettransactions.fromortouserid
                        END AS fromortouserid,
                    wallettransactions.debitamount,
                    wallettransactions.creditamount,
                    wallettransactions.pairid,
                    wallettransactions.createdon,
                    wallettransactions.businessproductid,
                    wallettransactions.parentid,
                    wallettransactions.transactionstatus,
                    wallettransactions.wallettypeid,
                    wallettransactions.channelid,
                    wallettransactions.description,
                    wallettransactions.instancetype,
                    wallettransactions.remarks
                   FROM wallettransactions
                  WHERE wallettransactions.creditamount > 0::numeric
                UNION ALL
                 SELECT pendingtransaction.executionid,
                    NULL::character varying AS businesstrxid,
                    pendingtransaction.touser AS fromortouserid,
                    pendingtransaction.debitreservedamount AS debitamount,
                    pendingtransaction.creditreservedamount AS creditamount,
                    NULL::character varying AS pairid,
                    pendingtransaction.createdon,
                    pendingtransaction.businessproductid,
                    NULL::character varying AS parentid,
                    pendingtransaction.transactionstatus,
                    pendingtransaction.creditwallettypeid AS wallettypeid,
                    pendingtransaction.channelid,
                    pendingtransaction.description,
                    NULL::character varying AS instancetype,
                    pendingtransaction.remarks
                   FROM pendingtransaction) trns
             LEFT JOIN users usr ON usr.id::text = trns.fromortouserid::text
             LEFT JOIN wallettype wtype ON wtype.id::text = trns.wallettypeid::text
             LEFT JOIN businessproduct bp ON bp.id::text = trns.businessproductid::text
             LEFT JOIN charges c ON c.id::text = trns.businessproductid::text
             LEFT JOIN channel ch ON ch.id::text = trns.channelid::text
             LEFT JOIN role rl ON rl.id::text = usr.roleid::text) cr ON cr.executionid::text = dr.executionid::text AND cr.businesstrxid::text = dr.businesstrxid::text AND cr.creditamount = dr.debitamount
  ORDER BY dr.createdon DESC;


-- dashboard.user_viewkev source

CREATE OR REPLACE VIEW dashboard.user_viewkev
AS SELECT row_number() OVER () AS snokev,
    u.username,
    r.name AS rolename,
    u.firstname,
    u.middlename,
    u.lastname,
    u.mobilenumber,
    to_char(u.createdon, 'yyyy-mm-dd HH24:MI:SS'::text) AS registrationdate,
    u.createdon,
    u.userstatus AS status,
    u.roletype,
    u.idtype,
    u.idnumber,
    u.deviceostype
   FROM users u
     LEFT JOIN role r ON u.roleid::text = r.id::text;


-- dashboard.wallet_balances source

CREATE OR REPLACE VIEW dashboard.wallet_balances
AS SELECT t2.firstname AS "First Name",
    t2.lastname AS "Last Name",
    t2.username AS "User Name",
    t2.city AS "City",
    t2.userstatus AS "User Status",
    t2.roletype AS "Role Type",
    t1.totalbalance AS "Wallet Balance"
   FROM ( SELECT walletbalance.totalbalance,
            walletbalance.ownerid
           FROM walletbalance) t1
     JOIN users t2 ON t2.id::text = t1.ownerid::text;


-- dashboard.walletonpos source

CREATE OR REPLACE VIEW dashboard.walletonpos
AS SELECT wt.txtime::timestamp(0) without time zone AS transactiondate,
    ( SELECT u.username
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.creditamount > 0::numeric) AS merchantid,
    ( SELECT u.firstname
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.creditamount > 0::numeric) AS merchantname,
    ( SELECT DISTINCT u.username
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.debitamount > 0::numeric) AS customerid,
    udd.referenceid AS terminalid,
    round(wt.creditamount, 2) AS amount,
    wt.businesstrxid AS artthatransactionid,
    wt.externaltransactionid AS postransactionid,
        CASE
            WHEN wt.parentid IS NULL THEN b.name
            ELSE c.name
        END AS transactiontype
   FROM wallettransactions wt
     LEFT JOIN users usr ON wt.fromortouserid::text = usr.id::text
     LEFT JOIN userdevicedetails udd ON wt.terminalid::text = udd.id::text
     LEFT JOIN businessproduct b ON wt.businessproductid::text = b.id::text
     LEFT JOIN charges c ON wt.businessproductid::text = c.id::text
  WHERE wt.creditamount > 0::numeric AND (wt.businessproductid::text = '1717c7e4-1fcc-4166-bb68-62a09dfe0668'::text OR (wt.businessproductid::text IN ( SELECT charges.id
           FROM charges
          WHERE charges.masterbpid::text = '1717c7e4-1fcc-4166-bb68-62a09dfe0668'::text)))
UNION ALL
 SELECT wt.txtime::timestamp(0) without time zone AS transactiondate,
    ( SELECT u.username
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.creditamount > 0::numeric) AS merchantid,
    ( SELECT u.firstname
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.creditamount > 0::numeric) AS merchantname,
    ( SELECT u.username
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.debitamount > 0::numeric) AS customerid,
    udd.referenceid AS terminalid,
    round(wt.creditamount, 2) AS amount,
    wt.businesstrxid AS artthatransactionid,
    wt.externaltransactionid AS postransactionid,
        CASE
            WHEN wt.parentid IS NULL THEN b.name
            ELSE c.name
        END AS transactiontype
   FROM wallettransactions wt
     LEFT JOIN users usr ON wt.fromortouserid::text = usr.id::text
     LEFT JOIN userdevicedetails udd ON wt.terminalid::text = udd.id::text
     LEFT JOIN businessproduct b ON wt.businessproductid::text = b.id::text
     LEFT JOIN charges c ON wt.businessproductid::text = c.id::text
  WHERE wt.creditamount > 0::numeric AND (wt.businessproductid::text = 'b71e26b1-e250-4bc3-bfc2-d2e00e4a7198'::text OR (wt.businessproductid::text IN ( SELECT charges.id
           FROM charges
          WHERE charges.masterbpid::text = 'b71e26b1-e250-4bc3-bfc2-d2e00e4a7198'::text)) OR (wt.businessproductid::text IN ( SELECT charges.id
           FROM charges
          WHERE (charges.masterbpid::text IN ( SELECT charges_1.id
                   FROM charges charges_1
                  WHERE charges_1.masterbpid::text = 'b71e26b1-e250-4bc3-bfc2-d2e00e4a7198'::text)))))
UNION ALL
 SELECT wt.txtime::timestamp(0) without time zone AS transactiondate,
    ( SELECT u.username
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.creditamount > 0::numeric) AS merchantid,
    ( SELECT u.firstname
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.debitamount > 0::numeric) AS merchantname,
    ( SELECT u.username
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.debitamount > 0::numeric) AS customerid,
    udd.referenceid AS terminalid,
    round(wt.debitamount, 2) AS amount,
    wt.businesstrxid AS artthatransactionid,
    wt.externaltransactionid AS postransactionid,
        CASE
            WHEN wt.parentid IS NULL THEN b.name
            ELSE c.name
        END AS transactiontype
   FROM wallettransactions wt
     LEFT JOIN users usr ON wt.fromortouserid::text = usr.id::text
     LEFT JOIN userdevicedetails udd ON wt.terminalid::text = udd.id::text
     LEFT JOIN businessproduct b ON wt.businessproductid::text = b.id::text
     LEFT JOIN charges c ON wt.businessproductid::text = c.id::text
  WHERE (wt.businessproductid::text = 'f680fff8-9c2a-46d5-a667-e6bdb7125603'::text OR (wt.businessproductid::text IN ( SELECT charges.id
           FROM charges
          WHERE charges.masterbpid::text = 'f680fff8-9c2a-46d5-a667-e6bdb7125603'::text)) OR (wt.businessproductid::text IN ( SELECT charges.id
           FROM charges
          WHERE (charges.masterbpid::text IN ( SELECT charges_1.id
                   FROM charges charges_1
                  WHERE charges_1.masterbpid::text = 'f680fff8-9c2a-46d5-a667-e6bdb7125603'::text))))) AND wt.debitamount > 0::numeric
UNION ALL
 SELECT wt.txtime::timestamp(0) without time zone AS transactiondate,
    ( SELECT u.username
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.debitamount > 0::numeric) AS merchantid,
    ( SELECT u.firstname
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND w.parentid IS NULL AND w.debitamount > 0::numeric) AS merchantname,
    ( SELECT u.username
           FROM users u
             JOIN wallettransactions w ON u.id::text = w.fromortouserid::text
          WHERE w.executionid::text = wt.executionid::text AND wt.parentid IS NULL AND w.creditamount > 0::numeric) AS customerid,
    udd.referenceid AS terminalid,
    round(wt.debitamount, 2) AS amount,
    wt.businesstrxid AS artthatransactionid,
    wt.externaltransactionid AS postransactionid,
        CASE
            WHEN wt.parentid IS NULL THEN b.name
            ELSE c.name
        END AS transactiontype
   FROM wallettransactions wt
     LEFT JOIN users usr ON wt.fromortouserid::text = usr.id::text
     LEFT JOIN userdevicedetails udd ON wt.terminalid::text = udd.id::text
     LEFT JOIN businessproduct b ON wt.businessproductid::text = b.id::text
     LEFT JOIN charges c ON wt.businessproductid::text = c.id::text
  WHERE wt.debitamount > 0::numeric AND (wt.businessproductid::text = '2308bc62-3f0c-408f-a1ad-e14f41026a4a'::text OR (wt.businessproductid::text IN ( SELECT charges.id
           FROM charges
          WHERE charges.masterbpid::text = '2308bc62-3f0c-408f-a1ad-e14f41026a4a'::text)) OR (wt.businessproductid::text IN ( SELECT charges.id
           FROM charges
          WHERE (charges.masterbpid::text IN ( SELECT charges_1.id
                   FROM charges charges_1
                  WHERE charges_1.masterbpid::text = '2308bc62-3f0c-408f-a1ad-e14f41026a4a'::text)))));

