-- DROP PROCEDURE "dataReports".proc_customer_kyc_info(varchar, timestamp, timestamp);

CREATE OR REPLACE PROCEDURE "dataReports".proc_customer_kyc_info(IN requestid character varying, IN start_date timestamp without time zone DEFAULT (concat((CURRENT_DATE - 1), ' ', '00:00:00'))::timestamp without time zone, IN end_date timestamp without time zone DEFAULT (concat((CURRENT_DATE - 1), ' ', '23:59:59'))::timestamp without time zone)
 LANGUAGE plpgsql
AS $procedure$

BEGIN

truncate "dataReports".rpt_customer_kyc_info;

insert into "dataReports".rpt_customer_kyc_info

SELECT requestId,

sno,

        id,

        createdby,

        username,

        firstname,

        middlename,

        lastname,

        mobilenumber,

        createdon::timestamp(0) without time zone AS registration_date,

        email,

        dateofbirth,

        gender,

        address,

        countrycode,

        state,

        citypincode,

        status,

        roletype,

        "ID Type",

        "ID Number",

        "Risk Rating",

    "Country",

    "Sanction Screening",

    ldapuser,

    "Employee Type",

    "Tax Number",

    "Monthly Income",

        "Nationality",

        "Occupation",

        rolename,

        referredby,

        kycdocumenttypes,

        kycprooftypes,

        "version",

        kycdocumentsname,

        kycupgraderequestdate,

        kycapproverequestdate,

        kycapproveruser,

        registeredbyagent from dashboard.customer_kyc_info_sftp

where  createdon::timestamp(0) without time zone  >= start_date

  AND createdon::timestamp(0) without time zone <= end_date;    

end;

$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_crbreport(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_crbreport(IN requestid character varying, IN run_date date DEFAULT (now() - '1 day'::interval))
 LANGUAGE plpgsql
AS $procedure$
begin
	truncate "dataReports".rpt_crbreport;
	insert into "dataReports".rpt_crbreport(requestid,FacilityStatusDate,Surname,FirstName,BranchCode,DOB,CustomerID,CurResAddr1,FacilityAccNum,Gender,Nationality,NatIDNum,MobileTel1,MaturityDate,FacilityAmount,DisbursementAmt,WrittenOffAmt,AmountCurrency,CurBal,AmountInArrears,NDIA,FacilityStatusCode,DisbursementDate,ClosedDate,ClosureReason,LastPaymentDate,LastPaymentAmount)
  	SELECT
		requestid,to_char(run_date::date::timestamp with time zone, 'yyyy/mm/dd'::text) as FacilityStatusDate,usr.lastname AS Surname,
		concat(usr.firstname , usr.middlename) AS FirstName,
    	'64'::text AS BranchCode,
    	to_char(usr.dob::date::timestamp with time zone, 'yyyy/mm/dd'::text) AS DOB,
    	usr.username AS CustomerID,
    	usr.address as CurResAddr1,
    	l.accountnumber as FacilityAccNum,
        CASE
            WHEN usr.gender::text = 'MALE'::text THEN 'M'::character varying
            WHEN usr.gender::text = 'FEMALE'::text THEN 'F'::character varying
            ELSE usr.gender
        END AS Gender,
    	'GHA'::text AS Nationality,
		usr.idnumber AS NatIDNum,
		concat('254', usr.username) AS MobileTel1,
--		'I'::text AS accountproducttype,
		to_char(l.expectedfirstrepaymentdate::date::timestamp with time zone, 'yyyy/mm/dd'::text) AS MaturityDate,
		round(l.principaldisbursed, 2)::numeric AS FacilityAmount,
		round(l.principaldisbursed, 2)::numeric AS DisbursementAmt,
		round(l.totalamountwrittenoff,2)::numeric as WrittenOffAmt,
		'GHS'::text AS AmountCurrency,
     	CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            ELSE round(l.totalamountoutstanding, 2)
        END AS CurBal,
    	(SELECT
			CASE
				WHEN loan.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
				WHEN loan.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
				WHEN date(loan.calucatedclosedate) >= date(run_date) THEN 0::numeric
				WHEN loan.totalamountoutstanding IS NULL THEN 0::numeric
				ELSE round(loan.totalamountoutstanding, 2)
			END AS round
	  	 	FROM loan
	  		WHERE loan.accountnumber::text = l.accountnumber::text) AS AmountInArrears,
        --CASE
            --WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            --WHEN  date(l.calucatedclosedate) >= date(run_date) THEN 0::numeric
        date_part('days'::text, l.expectedfirstrepaymentdate::timestamp with time zone - l.actualdisbursementdate::date::timestamp with time zone) * '1'::integer::double precision AS NDIA,
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN 'A'::text
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'C'::text
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 'W'::text
            ELSE 'C'::text
        END AS FacilityStatusCode,
    	to_char(l.actualdisbursementdate::date::timestamp with time zone, 'yyyy/mm/dd'::text) AS DisbursementDate,
    	to_char(l.actualclosedate::date::timestamp with time zone, 'yyyy/mm/dd'::text) AS ClosedDate,
    	'D' as ClosureReason,
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::date::timestamp with time zone, 'yyyy/mm/dd'::text)
        END AS LastPaymentDate,
        CASE
            WHEN l.lastinstallmentamount IS NULL THEN 0::numeric
            ELSE round(l.lastinstallmentamount, 2)::numeric
        END AS LastPaymentAmount
	FROM users usr
		JOIN loan l ON usr.id::text = l.userid::text 
			and (l.loanstatus in ('ACTIVE','WRITTEN_OFF') 
				or (l.loanstatus='CLOSED' and Date(l.actualclosedate)=date(run_date)))  
		LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
		LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
		LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text
		JOIN walletbalance wt ON usr.id::text = wt.ownerid::text
	WHERE wt.producttype::text = 'WALLET'::text;
end;
$procedure$
;

