            ELSE date_part('days'::text, l.calucatedclosedate::timestamp with time zone - run_date) * '-1'::integer::double precision
        END AS Days_in_arrears,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'Bucket 0'::text
            ELSE concat('Bucket ', round(lb.currentbucketnumber, 0))
        END AS Bucket,
		(SELECT
			CASE
				WHEN loan.loanstatus::text = 'CLOSED'::text THEN 0::numeric
				WHEN loan.loanstatus::text = 'WRITTEN_OFF'::text THEN round(l.totalamountwrittenoff, 2)
