        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::DATE,'dd/mm/yyyy')
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN to_char(l.writtenoffdate::DATE,'dd/mm/yyyy')
            else to_char(l.actualclosedate::DATE,'dd/mm/yyyy')
        END AS Account_status_Date,
		' '::text AS Reason_For_Closure,
