    	COALESCE(round(l.lastinstallmentamount, 2), 0::numeric) AS Latest_pymt_Amt,
        CASE
            WHEN l.loanstatus::text = ANY (ARRAY['ACTIVE'::character varying::text, 'WRITTEN_OFF'::character varying::text]) THEN 'ACTIVE'::text
            ELSE 'CLOSED'::text
        END AS Account_status_desc,
    	lp.name AS product_name,
		to_char(l.createdon,'dd/mm/yyyy HH24:MI:SS') AS createdon,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
            ELSE round(l.principaloutstanding, 2)
        END AS PrincipalOutstanding,
    	(SELECT
			CASE
		    	WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
				WHEN l.loanstatus::text = 'WRITTEN_OFF'::text THEN 0::numeric
				ELSE round(l.calcuatedintrest - l.interestrepaidsofar, 2)
			END AS round
        	FROM loanschedule ls
	  		WHERE ls.loanid::text = l.id::text LIMIT 1) AS Interestoutstanding, round(l.creditlimit, 2) AS Creditlimit,
		l.riskassessment AS RiskCategory,
        (SELECT 
				sum(round(l2.penaltypending, 2)) AS sum
				FROM loanschedule l2
				WHERE l2.loanid::text = l.id::text) AS Penaltyfeeoutstanding,
		(SELECT 
		 	sum(round(l2.penaltycomponent, 2)) AS sum
           	FROM loanschedule l2
          	WHERE l2.loanid::text = l.id::text) AS RolloverFees
	FROM users usr
 	JOIN loan l ON usr.id::text = l.userid::text and l.loanstatus::text = 'CLOSED'
 	LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
	LEFT JOIN loanbucket lb ON l.id::text = lb.loanid::text
	LEFT JOIN loanproduct lp ON l.loanproductid::text = lp.id::text;
end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_user_transaction(varchar, timestamp, timestamp);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_user_transaction(IN requestid character varying, IN start_date timestamp without time zone DEFAULT (concat((CURRENT_DATE - 1), ' ', '00:00:00'))::timestamp without time zone, IN end_date timestamp without time zone DEFAULT (concat((CURRENT_DATE - 1), ' ', '23:59:59'))::timestamp without time zone)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
truncate "dataReports".rpt_user_transaction;
insert into "dataReports".rpt_user_transaction
SELECT requestId, 
"Execution ID",
"Transaction ID",
"Payer",
"Payee",
"Amount",
"Transaction Date"::timestamp(0) without time zone AS "Transaction Date",
"TransactionType",
"Transaction Status",
"Channel",
"Payer Role",
"Payee Role",
"Description",
"Remarks",
"Reference",
"Voucher Details",
"ID Type",
"ID Number",
"Role",
"Mobile No.",
"Transaction Type",
"Depositor Name",
"Location",
"Agent/Hybrid Merchant Name",
"Consumer Unique Reference ID"
from dashboard.user_transaction
where  "Transaction Date"::timestamp(0) without time zone  >= start_date
  AND "Transaction Date"::timestamp(0) without time zone <= end_date;	
end;
$procedure$
;

