-- public.information_schema_gh source

CREATE OR REPLACE VIEW public.information_schema_gh
AS SELECT columns.table_catalog,
    columns.table_schema,
    columns.table_name,
    columns.column_name,
    columns.ordinal_position,
    'gh'::text AS country
   FROM information_schema.columns
  WHERE columns.table_schema::name = ANY (ARRAY['HadoopMigration'::name, 'public'::name]);


-- public.user_info source

CREATE OR REPLACE VIEW public.user_info
AS SELECT row_number() OVER () AS slno,
    u.username,
    r.name AS rolename,
    u.firstname,
    u.middlename,
    u.lastname,
    u.mobilenumber,
    u.createdon AS registrationdate,
    u.email,
    u.dob AS dateofbirth,
    u.gender,
    u.address,
    u.country,
    u.countrycode,
    u.passwordexpirydate,
    u.state,
    u.city,
    u.pincode AS citypincode,
    u.userstatus AS status,
    u.roletype,
    u.idtype,
    u.idnumber
   FROM users u
     LEFT JOIN role r ON u.roleid::text = r.id::text;

