		-- Functions

-- DROP FUNCTION public.absacodesfunc();

CREATE OR REPLACE FUNCTION public.absacodesfunc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
      INSERT INTO "HadoopMigration".absacodes_hadoop(sequenceid, id, statuscode, description, codetype) 
            values 
      (nextval('absacodes_seq'), new.id,new.statuscode,new.description,new.codetype);
      RETURN NEW;
   END;
$function$
;

-- DROP FUNCTION public.absacodesupdatefunc();

CREATE OR REPLACE FUNCTION public.absacodesupdatefunc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE "HadoopMigration".absacodes_hadoop 
set 
statuscode=new.statuscode,
description=new.description,
codetype=new.codetype
where
id = new.id;
RETURN NEW;
   END;
$function$
;

-- DROP FUNCTION public.atmconfigauditfunc();

CREATE OR REPLACE FUNCTION public.atmconfigauditfunc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
      INSERT INTO "HadoopMigration".atmconfigaudit_hadoop(sequenceid, auditid, id,createdby,createdon,modifiedby,modifiedon,atmname,businessproductid,atmartthapoolaccount,atmvoucherfundingaccount,denominationjson) 
            values 
      (nextval('atmconfigaudit_seq'), new.auditid, new.id,new.createdby,new.createdon,new.modifiedby,new.modifiedon,new.atmname,new.businessproductid,new.atmartthapoolaccount,new.atmvoucherfundingaccount,new.denominationjson);
      RETURN NEW;
   END;
$function$
;

-- DROP FUNCTION public.atmconfigauditupdatefunc();

CREATE OR REPLACE FUNCTION public.atmconfigauditupdatefunc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE "HadoopMigration".atmconfigaudit_hadoop 
set 
createdby=new.createdby,
createdon=new.createdon,
modifiedby=new.modifiedby,
modifiedon=new.modifiedon,
atmname=new.atmname,
businessproductid=new.businessproductid,
atmartthapoolaccount=new.atmartthapoolaccount,
atmvoucherfundingaccount=new.atmvoucherfundingaccount,
denominationjson=new.denominationjson
where
auditid = new.auditid;
RETURN NEW;
   END;
$function$
;

