-- DROP PROCEDURE public.proc_loanscore();

CREATE OR REPLACE PROCEDURE public.proc_loanscore()
 LANGUAGE sql
AS $procedure$
TRUNCATE TABLE loansummary;

INSERT INTO loansummary(userid,
NMobileOpenLoan,
NMobileLoanEver,
NMobileLoanClosedL12M,
MSinceFirstMobileLoanOpen,
MSinceMobileLoanClosed,
NMobileLoanDPDht60L12M,
NMaxDPDMobileLoanL12M,
NMaxDPDMobileLoanL6M,
ATotalPrincipalMobileLoan,
NMobileLoansPaidAdvL6M,
DSinceMobileLoanHT30DPD,
DSinceMobileLoanHT1DPD,
NMonthsMobileLoanWithPayments,
NGoodRepMobileLoanL6M,
NGoodRepMobileLoanL12M,
AMaxRepMobileLoanL12M,
NMonthsWith0MobileLoanL12M,
NMonthsMobileLoanWithProlongOrDPDht1L6M,
NMobileLoanProlongL6M,
NmobileLoansPast1M,
AMinDaysCloseOpenMobileLoanL12M,
days_betn_loans,
NLoansSinceLastLimitIncrease,
createdOn,
modifiedOn,
nmobileloanrejectedl6m,
nmobileloanrejectedl12m,
amaxutilmobileloanl12m
)
(WITH ln as (select distinct userid from loan)



SELECT distinct ln.userid, coalesce(q1.nMobileOpenLoan,0) as nMobileOpenLoan,
coalesce(q2.nmobileloanever,0), coalesce(q3.nmobileloanclosedl12m,0) as nmobileloanclosedl12m,
coalesce(q4.msincefirstmobileloanopen,0) as msincefirstmobileloanopen, coalesce(q5.msincemobileloanclosed,0) as msincemobileloanclosed,
coalesce(q6.nmobileloandpdht60l12m,0) as nmobileloandpdht60l12m, coalesce(q7.nmaxdpdmobileloanl12m, 0) as nmaxdpdmobileloanl12m,
coalesce(q8.nmaxdpdmobileloanl6m,0) as nmaxdpdmobileloanl6m, coalesce(q9.atotalprincipalmobileloan, 0) as atotalprincipalmobileloan,
coalesce(q10.nmobileloanspaidadvl6m,0) as nmobileloanspaidadvl6m, coalesce(q11.dsincemobileloanht30dpd,0) as dsincemobileloanht30dpd,
coalesce(q12.dsincemobileloanht1dpd,0) as dsincemobileloanht1dpd, coalesce(q13.nmonthsmobileloanwithpayments,0) as nmonthsmobileloanwithpayments,
coalesce(q14.ngoodrepmobileloanl6m,0) as ngoodrepmobileloanl6m, coalesce(q15.ngoodrepmobileloanl12m,0) as ngoodrepmobileloanl12m,
coalesce(q16.amaxrepmobileloanl12m,0) as amaxrepmobileloanl12m, coalesce(q17.nmonthswith0mobileloanl12m,0) as nmonthswith0mobileloanl12m,
coalesce(q18.nmonthsmobileloanwithprolongordpdht1l6m,0) as nmonthsmobileloanwithprolongordpdht1l6m, coalesce(q19.nmobileloanprolongl6m, nmobileloanprolongl6m,0) as nmobileloanprolongl6m, coalesce(q20.nmobileloanspast1m,0) as nmobileloanspast1m, coalesce(q21.amindayscloseopenmobileloanl12m,0) as amindayscloseopenmobileloanl12m, coalesce(q22.days_betn_loans,0) as days_betn_loans,
case when cl.lastlimitincreasedate is null then
(select count(*) from loan l where l.userid = ln.userid)
else
(select count(*) from loan l where l.createdon > cl.lastlimitincreasedate and l.userid = ln.userid) end as nloanssincelastlimitincrease,
now() as createdon, now() as modifiedOn, 0 As nmobileloanrejectedl6m, 0 as nmobileloanrejectedl12m, 0 as amaxutilmobileloanl12m



FROM ln
LEFT OUTER JOIN
(Select userid, count(*) as nMobileOpenLoan from loan
WHERE loanstatus = 'ACTIVE' or loanstatus = 'WRITTEN_OFF' GROUP BY userid) q1 on q1.userid = ln.userid
LEFT OUTER JOIN
(SELECT userid, count(*) as nmobileloanever from loan GROUP BY userid) q2 on q2.userid = ln.userid
LEFT OUTER JOIN
(SELECT userid, count(*) as nmobileloanclosedl12m from loan where loanstatus = 'CLOSED'
and date_part('days',age(now(),actualclosedate)) < 365 GROUP BY userid) q3 on q3.userid = ln.userid
LEFT OUTER JOIN
(select userid, date_part('months',age(now(), createdon)) as msincefirstmobileloanopen from loan order by createdon limit 1) q4 on q4.userid = ln.userid
LEFT OUTER JOIN
(select userid, case when loanstatus = 'ACTIVE' then 0 else
date_part('months', age(now(),modifiedon)) END as msincemobileloanclosed from loan order by createdon desc limit 1) q5 on q5.userid = ln.userid
LEFT OUTER JOIN
( SELECT sq1.userid, MAX(sq1.m1) as nmobileloandpdht60l12m from (
SELECT userid, max(DATE_PART('year', actualclosedate) - DATE_PART('year', expectedFirstRepaymentDate) * 12
+ DATE_PART('month', actualclosedate) - DATE_PART('month', expectedFirstRepaymentDate)) AS m1 from loan
WHERE loanstatus='CLOSED' and actualclosedate > expectedFirstRepaymentDate
AND DATE_PART('day', NOW()- actualclosedate) <=365
AND DATE_PART('day', actualclosedate - expectedFirstRepaymentDate) >= 60 GROUP BY userid
UNION ALL
select userid, max(DATE_PART('year', lastpaidon) - DATE_PART('year', expectedFirstRepaymentDate) * 12
+ DATE_PART('month', lastpaidon) - DATE_PART('month', expectedFirstRepaymentDate)) AS m1 from loan
where loanstatus<>'CLOSED' and NOW() > expectedFirstRepaymentDate
AND DATE_PART('day', NOW() - expectedFirstRepaymentDate) >= 60
GROUP BY userid) sq1 GROUP BY sq1.userid) q6 on q6.userid = ln.userid
LEFT OUTER JOIN
(select sq2.userid, max(sq2.days) as nmaxdpdmobileloanl12m from
(select userid, max(DATE_PART('day', actualclosedate - expectedFirstRepaymentDate)) AS days from loan
where loanstatus='CLOSED' and actualclosedate > expectedFirstRepaymentDate
and DATE_PART('day', NOW()- actualclosedate) <=365 GROUP BY userid
UNION ALL
select userid, max(DATE_PART('day', NOW() - expectedFirstRepaymentDate)) AS days from loan
where loanstatus<>'CLOSED'
and NOW() > expectedFirstRepaymentDate GROUP BY userid) AS sq2 GROUP BY sq2.userid) q7 on q7.userid = ln.userid
LEFT OUTER JOIN
(select userid, max(days) as nmaxdpdmobileloanl6m from
(select userid, max(DATE_PART('day', actualclosedate - expectedFirstRepaymentDate)) AS days from loan
where loanstatus='CLOSED' and actualclosedate > expectedFirstRepaymentDate
and DATE_PART('day', NOW()- actualclosedate) <=180 GROUP BY userid
UNION ALL
select userid, max(DATE_PART('day', NOW() - expectedFirstRepaymentDate)) AS days from loan
where loanstatus<>'CLOSED' and NOW() > expectedFirstRepaymentDate GROUP BY userid) AS sq3 GROUP BY sq3.userid) q8 on q8.userid = ln.userid
LEFT OUTER JOIN
(select userid, sum(principalgranted) as atotalprincipalmobileloan from loan GROUP BY userid) q9 on q9.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspaidadvl6m from loan where loanstatus = 'CLOSED' and
calucatedclosedate > modifiedon and date_part('days',age(now(),modifiedon)) < 180 GROUP BY userid) q10 on q10.userid = ln.userid
LEFT OUTER JOIN
(select userid, case when loanstatus = 'ACTIVE' and date_part('days',age(now(), calucatedclosedate)) > 30
then (date_part('days',age(now(), calucatedclosedate))-30) else 0 end as dsincemobileloanht30dpd from loan order by createdon desc limit 1) q11 on q11.userid = ln.userid
LEFT OUTER JOIN
(select userid,case when loanstatus = 'ACTIVE' and date_part('days',age(now(), calucatedclosedate)) > 1
then (date_part('days',age(now(), calucatedclosedate)) -1) else 0 end as dsincemobileloanht1dpd from loan order by createdon desc limit 1) q12 on q12.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmonthsmobileloanwithpayments from loan where lastpaidon is not null GROUP BY userid) q13 on q13.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as ngoodrepmobileloanl6m from loan where loanstatus = 'CLOSED'
and modifiedon < calucatedclosedate and
date_part('days', age(now(), modifiedon)) < 180 GROUP BY userid) q14 on q14.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as ngoodrepmobileloanl12m from loan where loanstatus = 'CLOSED'
and modifiedon < calucatedclosedate and
date_part('days', age(now(), modifiedon)) < 365 GROUP BY userid) q15 on q15.userid = ln.userid
LEFT OUTER JOIN
(select userid, max(lastinstallmentamount) as amaxrepmobileloanl12m from loan where loanstatus = 'CLOSED'
and date_part('days', age(now(), actualclosedate)) < 365 GROUP BY userid) q16 on q16.userid = ln.userid
LEFT OUTER JOIN
(select userid, case when loanstatus = 'ACTIVE' then 0 else
date_part('months', age(now(), lastpaidon)) end as nmonthswith0mobileloanl12m from loan
order by createdon desc limit 1) q17 on q17.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmonthsmobileloanwithprolongordpdht1l6m from loan where loanstatus = 'CLOSED' and
modifiedon > calucatedclosedate GROUP BY userid) q18 on q18.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanprolongl6m from loan where loanstatus = 'CLOSED' and
modifiedon > calucatedclosedate GROUP BY userid) q19 on q19.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast1m from loan
where date_part('days', age(now(), createdon)) < 31 GROUP BY userid) q20 on q20.userid = ln.userid
LEFT OUTER JOIN
(select userid, min(date_part('days', age(modifiedon, createdon))) as amindayscloseopenmobileloanl12m from loan
where loanstatus = 'CLOSED' GROUP BY userid) q21 on q21.userid = ln.userid
LEFT OUTER JOIN
(select sq5.userid, date_part('days', age(sq5.new_date, sq5.prev_date)) as days_betn_loans from (
select sq4.userid, sq4.prev_date, sq4.new_date, ROW_NUMBER() OVER ( partition by sq4.userid order by sq4.createdon desc) as rowno from (
select lo.userid, lo.createdon, lag(lo.actualdisbursementdate) over (partition by lo.userid order by lo.createdon)
as prev_date, lo.actualdisbursementdate as new_date from loan lo order by createdon desc) as sq4) as sq5 where rowno=1) q22 on q22.userid = ln.userid
LEFT OUTER JOIN
creditlimit cl on ln.userid = cl.userid);
$procedure$
;

