CREATE OR REPLACE FUNCTION public.walletbalancefunc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
      INSERT INTO "HadoopMigration".walletbalance_hadoop(sequenceid, id, createdby, createdon, modifiedby, modifiedon, transactiontime, producttype, instancetype, walletstatus, currencyid, ownerid, creditamount, debitamount, totalbalance, reservebalance,  maxcreditamountlimit, maxdebitamountlimit, uppertotalbalancelimit, lowertotalbalancelimit, dailymaxdebitamount, dailymaxcreditamount, dailymaxtotalamount, dailymaxcreditcount, dailymaxdebitcount, dailymaxtotalcount, weeklymaxdebitamount, weeklymaxcreditamount, weeklymaxtotalamount, weeklymaxcreditcount, weeklymaxdebitcount, weeklymaxtotalcount, monthlymaxdebitamount, monthlymaxcreditamount, monthlymaxtotalamount, monthlymaxcreditcount, monthlymaxdebitcount, monthlymaxtotalcount, isactive, needssettlement, settlementinterval, settlementaccountid, checksum, consolidatetransactions, hotaccount, minimumbalance, productusermappingid, thisdaystatjson, thismonthstatjson, thisweekstatjson, walletno, walletstatjson, wallettypeid) 
            values 
      (nextval('walletbalance_seq'), new.id, new.createdby, new.createdon, new.modifiedby, new.modifiedon, new.transactiontime, new.producttype, new.instancetype, new.walletstatus, new.currencyid, new.ownerid, new.creditamount, new.debitamount, new.totalbalance, new.reservebalance,  new.maxcreditamountlimit, new.maxdebitamountlimit, new.uppertotalbalancelimit, new.lowertotalbalancelimit, new.dailymaxdebitamount, new.dailymaxcreditamount, new.dailymaxtotalamount, new.dailymaxcreditcount, new.dailymaxdebitcount, new.dailymaxtotalcount, new.weeklymaxdebitamount, new.weeklymaxcreditamount, new.weeklymaxtotalamount, new.weeklymaxcreditcount, new.weeklymaxdebitcount, new.weeklymaxtotalcount, new.monthlymaxdebitamount, new.monthlymaxcreditamount, new.monthlymaxtotalamount, new.monthlymaxcreditcount, new.monthlymaxdebitcount, new.monthlymaxtotalcount, new.isactive, new.needssettlement, new.settlementinterval, new.settlementaccountid, new.checksum, new.consolidatetransactions, new.hotaccount, new.minimumbalance, new.productusermappingid, new.thisdaystatjson, new.thismonthstatjson, new.thisweekstatjson, new.walletno, new.walletstatjson, new.wallettypeid);
      RETURN NEW;
   END;
$function$
;

-- DROP PROCEDURE public.walletbalancesnapshotdbdt(date);

CREATE OR REPLACE PROCEDURE public.walletbalancesnapshotdbdt(IN dt date)
 LANGUAGE plpgsql
AS $procedure$
DECLARE
BEGIN
INSERT into walletBalanceSnapshot(id,walletbalanceid,debitamount,creditamount,totalbalance, wallettypeid,isactive,snapshottime,lienamount)
	SELECT  uuid_generate_v4(),
	walletBalance.id,
	walletBalance.debitamount,
	walletBalance.creditamount ,
	walletBalance.totalbalance ,
	walletBalance.wallettypeid , 
	walletBalance.isactive, 
	dt as "SnapshotTime", 
	case WHEN walletLienRecord.lienamount is not null then walletLienRecord.lienamount::numeric else 0  END AS "lienamount"
	from walletBalance
	left join  walletLienRecord on walletLienRecord.walletbalanceid =  walletBalance.id  and walletLienRecord.status = 'ACTIVE'
where walletBalance.isactive is true and walletBalance.producttype = 'WALLET';
END $procedure$
;

